{"command":"create","path":"/workspace/codebase/rust-cli/src/glob.rs","file_text":"//! A small glob matcher that mirrors the subset of `picomatch` semantics used
//! by jscodeshift's ignore-file handling (see `src/ignoreFiles.js` in the
//! original JavaScript implementation).
//!
//! Supported syntax:
//!   - `*`   matches any run of characters except `/`
//!   - `**`  matches any run of characters, including `/`
//!   - `?`   matches a single character except `/`
//!   - `[...]` character classes (including `[!...]`/`[^...]` negation)
//!   - `{a,b,c}` brace alternation (no nesting)
//!   - a leading `!` negates the whole pattern (gitignore-style)
//!
//! `dot: true` semantics (as used by jscodeshift) are always applied: `*`
//! and `**` are allowed to match leading dots in path segments.

pub struct GlobPattern {
    negated: bool,
    regex: regex::Regex,
}

impl GlobPattern {
    pub fn new(pattern: &str) -> Option<GlobPattern> {
        let (negated, body) = if let Some(rest) = pattern.strip_prefix('!') {
            (true, rest)
        } else {
            (false, pattern)
        };
        let regex_src = translate(body);
        let regex = regex::Regex::new(&regex_src).ok()?;
        Some(GlobPattern { negated, regex })
    }

    fn is_match(&self, path: &str) -> bool {
        self.regex.is_match(path)
    }
}

/// Mirrors `picomatch.isMatch(path, patterns, { dot: true })`: true if any
/// non-negated pattern matches and no later negated pattern un-matches it.
pub fn is_match(path: &str, patterns: &[GlobPattern]) -> bool {
    let mut matched = false;
    for pattern in patterns {
        if pattern.negated {
            if matched && pattern.is_match(path) {
                matched = false;
            }
        } else if pattern.is_match(path) {
            matched = true;
        }
    }
    matched
}

fn translate(pattern: &str) -> String {
    let mut out = String::from("^");
    let chars: Vec<char> = pattern.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        match c {
            '*' => {
                if i + 1 < chars.len() && chars[i + 1] == '*' {
                    // `**` — match anything, including path separators.
                    // Consume any following slash so `**/` behaves like a
                    // "zero or more directories" prefix.
                    i += 2;
                    if i < chars.len() && chars[i] == '/' {
                        out.push_str("(?:.*/)?");
                        i += 1;
                    } else {
                        out.push_str(".*");
                    }
                    continue;
                } else {
                    out.push_str("[^/]*");
                }
            }
            '?' => out.push_str("[^/]"),
            '[' => {
                let mut j = i + 1;
                let negate = j < chars.len() && (chars[j] == '!' || chars[j] == '^');
                if negate {
                    j += 1;
                }
                let start_class = j;
                while j < chars.len() && chars[j] != ']' {
                    j += 1;
                }
                if j >= chars.len() {
                    // No closing bracket; treat `[` literally.
                    out.push_str("\\[");
                } else {
                    out.push('[');
                    if negate {
                        out.push('^');
                    }
                    let class_body: String = chars[start_class..j].iter().collect();
                    out.push_str(&escape_class(&class_body));
                    out.push(']');
                    i = j;
                }
            }
            '{' => {
                let mut j = i + 1;
                let mut depth = 1;
                while j < chars.len() && depth > 0 {
                    match chars[j] {
                        '{' => depth += 1,
                        '}' => depth -= 1,
                        _ => {}
                    }
                    if depth == 0 {
                        break;
                    }
                    j += 1;
                }
                if j < chars.len() {
                    let inner: String = chars[i + 1..j].iter().collect();
                    let alts: Vec<String> = inner.split(',').map(|a| translate_fragment(a)).collect();
                    out.push_str("(?:");
                    out.push_str(&alts.join("|"));
                    out.push(')');
                    i = j;
                } else {
                    out.push_str("\\{");
                }
            }
            '.' | '+' | '(' | ')' | '^' | '$' | '|' | '\\' => {
                out.push('\\');
                out.push(c);
            }
            '/' => out.push('/'),
            _ => out.push(c),
        }
        i += 1;
    }
    out.push('$');
    out
}

fn translate_fragment(fragment: &str) -> String {
    // Translate a brace-alternative without the anchors, reusing the same
    // core logic by stripping the leading `^`/trailing `$` added by
    // `translate`.
    let full = translate(fragment);
    full.trim_start_matches('^').trim_end_matches('$').to_string()
}

fn escape_class(body: &str) -> String {
    // Character classes are passed through mostly verbatim; only escape the
    // backslash itself so accidental control sequences don't leak in.
    body.replace('\\', "\\\\")
}
"}

{"command":"create","path":"/workspace/codebase/rust-cli/src/ignore.rs","file_text":"//! Port of `src/ignoreFiles.js`.

use crate::glob::{is_match, GlobPattern};
use std::fs;
use std::sync::Mutex;

pub struct IgnoreList {
    patterns: Mutex<Vec<GlobPattern>>,
    raw: Mutex<Vec<String>>,
}

impl IgnoreList {
    pub fn new() -> IgnoreList {
        IgnoreList {
            patterns: Mutex::new(Vec::new()),
            raw: Mutex::new(Vec::new()),
        }
    }

    fn add_pattern(&self, val: &str) {
        if val.is_empty() || val.starts_with('#') {
            return;
        }
        let mut variants: Vec<String> = Vec::new();
        if !val.contains('/') {
            variants.push(format!("**/{}", val));
        } else if val.ends_with('/') {
            variants.push(format!("**/{}**", val));
            variants.push(format!("{}**", val));
        }
        variants.push(val.to_string());

        let mut patterns = self.patterns.lock().unwrap();
        let mut raw = self.raw.lock().unwrap();
        for v in variants {
            if let Some(p) = GlobPattern::new(&v) {
                patterns.push(p);
                raw.push(v);
            }
        }
    }

    /// Mirrors `exports.add` (`addIgnoreFromInput`).
    pub fn add<I, S>(&self, input: Option<I>)
    where
        I: IntoIterator<Item = S>,
        S: AsRef<str>,
    {
        if let Some(items) = input {
            for item in items {
                self.add_pattern(item.as_ref());
            }
        }
    }

    pub fn add_one(&self, value: Option<&str>) {
        if let Some(v) = value {
            self.add_pattern(v);
        }
    }

    /// Mirrors `exports.addFromFile` (`addIgnoreFromFile`).
    pub fn add_from_file(&self, paths: &[String]) {
        let mut lines: Vec<String> = Vec::new();
        for config in paths {
            if let Ok(metadata) = fs::metadata(config) {
                if metadata.is_file() {
                    if let Ok(content) = fs::read_to_string(config) {
                        for line in content.split(['\n']) {
                            let line = line.strip_suffix('\r').unwrap_or(line);
                            lines.push(line.to_string());
                        }
                    }
                }
            }
        }
        for line in lines {
            self.add_pattern(&line);
        }
    }

    pub fn add_from_file_one(&self, path: Option<&str>) {
        if let Some(p) = path {
            self.add_from_file(&[p.to_string()]);
        }
    }

    pub fn should_ignore(&self, path: &str) -> bool {
        let patterns = self.patterns.lock().unwrap();
        if patterns.is_empty() {
            return false;
        }
        if is_match(path, &patterns) {
            return true;
        }
        // Strip a leading `./` or `../` traversal prefix (possibly repeated)
        // so relative source paths behave the same as absolute/plain
        // relative ones. See https://github.com/facebook/jscodeshift/issues/556
        let normalized = strip_leading_traversal(path);
        if normalized != path {
            return is_match(&normalized, &patterns);
        }
        false
    }
}

fn strip_leading_traversal(path: &str) -> String {
    let bytes = path.as_bytes();
    let mut i = 0;
    loop {
        if i < bytes.len() && bytes[i] == b'.' {
            let mut j = i + 1;
            if j < bytes.len() && bytes[j] == b'.' {
                j += 1;
            }
            if j < bytes.len() && (bytes[j] == b'/' || bytes[j] == b'\\') {
                i = j + 1;
                continue;
            }
        }
        break;
    }
    path[i..].to_string()
}
"}

