pub struct ParsedArgs {
    pub positional: Vec<Value>,
    pub options: HashMap<String, Value>,
    /// Set if `--help` or `--version` (or an unknown "callback" option) was
    /// requested; contains the text that should be printed and exit(0).
    pub callback_output: Option<String>,
}

pub struct ArgsError {
    pub exit_code: i32,
    pub message: String,
}

fn is_option(s: &str) -> bool {
    s.starts_with('-')
}

fn format_option(o: &OptionSpec) -> String {
    let mut text = String::from("  ");
    if let Some(a) = o.abbr {
        text.push_str(&format!("-{}, ", a));
    } else {
        text.push_str("    ");
    }
    text.push_str(&format!("--{}{}", if o.flag { "(no-)" } else { "" }, o.full));
    if let Some(choices) = &o.choices {
        let joined: Vec<String> = choices.iter().map(value_to_display).collect();
        text.push_str(&format!("={}", joined.join("|")));
    } else if let Some(mv) = o.metavar {
        text.push_str(&format!("={}", mv));
    }
    if o.list {
        text.push_str(" ...");
    }
    if o.default_help.is_some() || o.default.is_some() || o.help.is_some() {
        text.push_str("  ");
        if text.len() < 32 {
            text.push_str(&" ".repeat(32 - text.len()));
        }
        let text_length = text.len();
        if let Some(h) = o.help {
            text.push_str(h);
        }
        if o.default_help.is_some() || o.default.is_some() {
            if o.help.is_some() {
                text.push('\n');
            }
            let default_display = o
                .default_help
                .map(|s| s.to_string())
                .unwrap_or_else(|| value_to_display(o.default.as_ref().unwrap()));
            text.push_str(&" ".repeat(text_length));
            text.push_str(&format!("(default: {})", default_display));
        }
    }
    text
}

fn value_to_display(v: &Value) -> String {
    match v {
        Value::String(s) => s.clone(),
        Value::Number(n) => n.to_string(),
        Value::Bool(b) => b.to_string(),
        other => other.to_string(),
    }
}

pub fn get_help_text(options: &[OptionSpec]) -> String {
    let mut opts: Vec<&OptionSpec> = options.iter().collect();
    opts.sort_by_key(|o| o.display_index);
    let body: Vec<String> = opts.iter().map(|o| format_option(o)).collect();
    let text = format!(
        "\nUsage: jscodeshift [OPTION]... PATH...\n  or:  jscodeshift [OPTION]... -t TRANSFORM_PATH PATH...\n  or:  jscodeshift [OPTION]... -t URL PATH...\n  or:  jscodeshift [OPTION]... --stdin < file_list.txt\n\nApply transform logic in TRANSFORM_PATH (recursively) to every PATH.\nIf --stdin is set, each line of the standard input is used as a path.\n\nOptions:\n\"...\" behind an option means that it can be supplied multiple times.\nAll options are also passed to the transformer, which means you can supply custom options that are not listed here.\n\n{}\n",
        body.join("\n")
    );
    text.trim_start().to_string()
}

fn process_value(kind: ProcessKind, raw: &str) -> Result<Value, ArgsError> {
    match kind {
        ProcessKind::Json => Ok(serde_json::from_str(raw).unwrap_or_else(|_| Value::String(raw.to_string()))),
        ProcessKind::Number => {
            let n: f64 = raw.parse().unwrap_or(f64::NAN);
            Ok(serde_json::json!(n))
        }
        ProcessKind::JsonFile => {
            let content = std::fs::read_to_string(raw).map_err(|e| ArgsError {
                exit_code: 1,
                message: format!("{}", e),
            })?;
            serde_json::from_str(&content).map_err(|e| ArgsError {
                exit_code: 1,
                message: format!("{}", e),
            })
        }
    }
}

/// Mirrors `argsParser.parse`. `version_text` and `help_text` are the
/// callback outputs for `--version`/`--help` (computed by the caller since
/// they depend on runtime state like package/dependency versions).
pub fn parse(
    options: &[OptionSpec],
    args: &[String],
    version_text: impl FnOnce() -> String,
) -> Result<ParsedArgs, ArgsError> {
    #[derive(PartialEq, Eq, Clone)]
    enum Slot {
        Missing,
        Present(Value),
    }

    let mut by_flag_name: HashMap<String, usize> = HashMap::new();
    for (i, o) in options.iter().enumerate() {
        by_flag_name.insert(format!("--{}", o.full), i);
        if let Some(a) = o.abbr {
            by_flag_name.insert(format!("-{}", a), i);
        }
        if o.flag {
            by_flag_name.insert(format!("--no-{}", o.full), i);
        }
    }

    let mut parsed: HashMap<String, Slot> = HashMap::new();
    for o in options {
        if let Some(d) = &o.default {
            parsed.insert(o.key.to_string(), Slot::Present(d.clone()));
        } else if o.list {
            parsed.insert(o.key.to_string(), Slot::Present(Value::Array(vec![])));
        }
    }

    let mut positional: Vec<Value> = Vec::new();
    let mut callback_output: Option<String> = None;

    let mut i = 0usize;
    while i < args.len() {
        let arg = &args[i];
        if is_option(arg) {
            let mut option_name = arg.clone();
            let mut value: Option<String> = None;
            if let Some(idx) = arg.find('=') {
                option_name = arg[..idx].to_string();
                value = Some(arg[idx + 1..].to_string());
            }

            if let Some(&opt_idx) = by_flag_name.get(&option_name) {
                let o = &options[opt_idx];

                if o.key == "help" {
                    callback_output = Some(get_help_text(options));
                    break;
                }
                if o.key == "version" {
                    callback_output = Some(version_text());
                    break;
                }

                if o.flag {
                    let v = if option_name.starts_with("--no-") {
                        false
                    } else if let Some(val) = &value {
                        val == "1"
                    } else {
                        true
                    };
                    parsed.insert(o.key.to_string(), Slot::Present(Value::Bool(v)));
                } else {
                    if value.is_none() && i < args.len() - 1 && !is_option(&args[i + 1]) {
                        value = Some(args[i + 1].clone());
                        i += 1;
                    }
                    if let Some(v) = value {
                        let processed = process_value(o.process, &v)?;
                        if o.list {
                            let entry = parsed.entry(o.key.to_string()).or_insert(Slot::Present(Value::Array(vec![])));
                            if let Slot::Present(Value::Array(arr)) = entry {
                                arr.push(processed);
                            }
                        } else {
                            parsed.insert(o.key.to_string(), Slot::Present(processed));
                        }
                    } else {
                        parsed.insert(o.key.to_string(), Slot::Missing);
                    }
                }
            } else {
                // Unknown option passthrough, mirrors the JS "else" branch.
                let real_option_name = strip_dashes_and_no(&option_name);
                let existing = parsed.get(&real_option_name).cloned();
                let is_list = matches!(&existing, Some(Slot::Present(v)) if !matches!(v, Value::Bool(true)));

                let next_is_option = args.get(i + 1).map(|s| is_option(s)).unwrap_or(false);
                let is_flag = existing.is_none() && value.is_none() && next_is_option;

                if is_list {
                    if let Some(Slot::Present(current)) = existing.clone() {
                        if !matches!(current, Value::Array(_)) {
                            let new_arr = if matches!(current, Value::Bool(true)) {
                                Value::Array(vec![])
                            } else {
                                Value::Array(vec![current])
                            };
                            parsed.insert(real_option_name.clone(), Slot::Present(new_arr));
                        }
                    }
                }

                if is_flag {
                    let v = if option_name.starts_with("--no-") {
                        false
                    } else if let Some(val) = &value {
                        val == "1"
                    } else {
                        true
                    };
                    parsed.insert(real_option_name.clone(), Slot::Present(Value::Bool(v)));
                } else {
                    if value.is_none() && i < args.len() - 1 && !is_option(&args[i + 1]) {
                        value = Some(args[i + 1].clone());
                        i += 1;
                    }
                    if let Some(v) = value {
                        let processed: Value = serde_json::from_str(&v).unwrap_or(Value::String(v));
                        if is_list {
                            let entry = parsed.entry(real_option_name.clone()).or_insert(Slot::Present(Value::Array(vec![])));
                            if let Slot::Present(Value::Array(arr)) = entry {
                                arr.push(processed);
                            }
                        } else {
                            parsed.insert(real_option_name.clone(), Slot::Present(processed));
                        }
                    } else {
                        parsed.insert(real_option_name.clone(), Slot::Missing);
                    }
                }
            }
        } else {
            let as_number = arg.parse::<i64>();
            if let Ok(n) = as_number {
                if arg.chars().all(|c| c.is_ascii_digit()) {
                    positional.push(Value::Number(n.into()));
                } else {
                    positional.push(Value::String(arg.clone()));
                }
            } else {
                positional.push(Value::String(arg.clone()));
            }
        }
        i += 1;
    }

    if let Some(text) = callback_output {
        return Ok(ParsedArgs {
            positional,
            options: HashMap::new(),
            callback_output: Some(text),
        });
    }

    let mut errors = Vec::new();
    let mut final_options = HashMap::new();
    for (k, slot) in &parsed {
        match slot {
            Slot::Missing => {
                if let Some(o) = options.iter().find(|o| o.key == k) {
                    return Err(ArgsError {
                        exit_code: 1,
                        message: format!(
                            "Missing value: --{} requires a value\n\n---\n\n{}",
                            o.full,
                            get_help_text(options)
                        ),
                    });
                }
            }
            Slot::Present(v) => {
                final_options.insert(k.clone(), v.clone());
            }
        }
    }

    for o in options {
        if let Some(choices) = &o.choices {
            let val = final_options.get(o.key);
            let ok = val.map(|v| choices.contains(v)).unwrap_or(false);
            if !ok {
                let joined: Vec<String> = choices.iter().map(value_to_display).collect();
                errors.push(format!(
                    "Error: --{} must be one of the values {}",
                    o.full,
                    joined.join(",")
                ));
            }
        }
    }
    if !errors.is_empty() {
        return Err(ArgsError {
            exit_code: 1,
            message: format!("{}\n\n---\n\n{}", errors.join("\n"), get_help_text(options)),
        });
    }

    Ok(ParsedArgs {
        positional,
        options: final_options,
        callback_output: None,
    })
}

fn strip_dashes_and_no(name: &str) -> String {
    let s = name.trim_start_matches('-');
    s.strip_prefix("no-").unwrap_or(s).to_string()
}
"}

{"command":"create","path":"/workspace/codebase/bridge/transform-host.js","file_text":"#!/usr/bin/env node

/**
 * Copyright (c) Facebook, Inc. and its affiliates.
 *
 * This source code is licensed under the MIT license found in the
 * LICENSE file in the root directory of this source tree.
 */

'use strict';

/**
 * Minimal JavaScript bridge used by the Rust CLI/runner to load and execute
 * a jscodeshift transform. This replaces the process-fork/IPC protocol that
 * `src/Worker.js` used to speak with `src/Runner.js`; the Rust `Runner`
 * spawns this script as a child process and exchanges newline-delimited
 * JSON messages over stdin/stdout instead of Node's `child_process` IPC
 * channel.
 *
 * Protocol:
 *   - argv[2]/argv[3]: transform file path / "babel"|"no-babel" flag, same
 *     meaning as the old `Worker.js` argv-based setup.
 *   - stdin: newline-delimited JSON objects `{ files: string[], options }`.
 *     An object with an empty `files` array signals there is no more work
 *     and the process should exit.
 *   - stdout: two kinds of lines.
 *       * Control frames: JSON prefixed with `\u0000` (NUL), one of
 *         `{action:"status",...}`, `{action:"update",...}`,
 *         `{action:"report",...}`, `{action:"free"}`, or
 *         `{action:"disconnect"}`. These mirror the messages `Worker.js`
 *         used to send over IPC.
 *       * Anything else is plain output produced by the transform itself
 *         (i.e. `console.log` from the `--print` option) and must be
 *         forwarded to the real terminal verbatim, exactly like it was
 *         before when the child process's stdout was inherited.
 */

const fs = require('graceful-fs');
const writeFileAtomic = require('write-file-atomic');
const { DEFAULT_EXTENSIONS } = require('@babel/core');
const getParser = require('../src/getParser');
const jscodeshift = require('../src/core');

let presetEnv;
try {
  presetEnv = require('@babel/preset-env');
} catch (_) {}

let transform;
let parserFromTransform;

const CONTROL_PREFIX = '\u0000';

function notify(data) {
  process.stdout.write(CONTROL_PREFIX + JSON.stringify(data) + '\n');
}

function free() {
  notify({ action: 'free' });
}

function disconnect() {
  notify({ action: 'disconnect' });
}

function updateStatus(status, file, msg) {
  msg = msg ? file + ' ' + msg : file;
  notify({ action: 'status', status: status, msg: msg });
}

function report(file, msg) {
  notify({ action: 'report', file, msg });
}

function empty() {}

function stats(name, quantity) {
  quantity = typeof quantity !== 'number' ? 1 : quantity;
  notify({ action: 'update', name: name, quantity: quantity });
}

function trimStackTrace(trace) {
  if (!trace) {
    return '';
  }
  const lines = trace.split('\n');
  const result = [];
  lines.every(function (line) {
    if (line.indexOf(__filename) === -1) {
      result.push(line);
      return true;
    }
  });
  return result.join('\n');
}

function prepareJscodeshift(options) {
  const parser = parserFromTransform || getParser(options.parser, options.parserConfig);
  return jscodeshift.withParser(parser);
}

function setup(tr, babel) {
  if (babel === 'babel') {
    const presets = [];
    if (presetEnv) {
      presets.push([presetEnv.default, { targets: { node: true } }]);
    }
    presets.push(
      /\.tsx?$/.test(tr)
        ? require('@babel/preset-typescript').default
        : require('@babel/preset-flow').default
    );

    require('@babel/register')({
      configFile: false,
      babelrc: false,
      presets,
      plugins: [
        require('@babel/plugin-transform-class-properties').default,
        require('@babel/plugin-transform-nullish-coalescing-operator').default,
        require('@babel/plugin-transform-optional-chaining').default,
        require('@babel/plugin-transform-modules-commonjs').default,
        require('@babel/plugin-transform-private-methods').default,
      ],
      extensions: [...DEFAULT_EXTENSIONS, '.ts', '.tsx'],
      ignore: [
        /@babel\/parser/,
        /\/flow-parser\//,
        /\/recast\//,
        /\/ast-types\//,
      ],
    });
  }

  const module_ = require(tr);
  transform = typeof module_.default === 'function' ? module_.default : module_;
  if (module_.parser) {
    parserFromTransform =
      typeof module_.parser === 'string' ? getParser(module_.parser) : module_.parser;
  }
}

function processFile(file, options) {
  return new Promise((resolve) => {
    fs.readFile(file, async function (err, source) {
      if (err) {
        updateStatus('error', file, 'File error: ' + err);
        resolve();
        return;
      }
      source = source.toString();
      try {
        const jscodeshiftInstance = prepareJscodeshift(options);
        const out = await transform(
          { path: file, source: source },
          {
            j: jscodeshiftInstance,
            jscodeshift: jscodeshiftInstance,
            stats: options.dry ? stats : empty,
            report: (msg) => report(file, msg),
          },
          options
        );
        if (!out || out === source) {
          updateStatus(out ? 'nochange' : 'skip', file);
          resolve();
          return;
        }
        if (options.print) {
          console.log(out); // eslint-disable-line no-console
        }
        if (!options.dry) {
          writeFileAtomic(file, out, function (err) {
            if (err) {
              updateStatus('error', file, 'File writer error: ' + err);
            } else {
              updateStatus('ok', file);
            }
            resolve();
          });
        } else {
          updateStatus('ok', file);
          resolve();
        }
      } catch (err) {
        updateStatus(
          'error',
          file,
          'Transformation error (' +
            err.message.replace(/\n/g, ' ') +
            ')\n' +
            trimStackTrace(err.stack)
        );
        resolve();
      }
    });
  });
}

async function run(data) {
  const files = data.files || [];
  const options = data.options || {};
  if (!files.length) {
    disconnect();
    return;
  }
  await Promise.all(files.map((file) => processFile(file, options)));
  free();
}

setup(process.argv[2], process.argv[3]);

let buffer = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', (chunk) => {
  buffer += chunk;
  let index;
  while ((index = buffer.indexOf('\n')) !== -1) {
    const line = buffer.slice(0, index);
    buffer = buffer.slice(index + 1);
    if (line.trim() === '') continue;
    const data = JSON.parse(line);
    run(data);
  }
});
process.stdin.on('end', () => {
  // Nothing to do; the last `run()` call (with an empty file list) is
  // responsible for triggering `disconnect()`.
});
"}

{"command":"create","path":"/workspace/codebase/rust-cli/src/worker.rs","file_text":"//! Manages a single `bridge/transform-host.js` child process: the Rust
//! counterpart to a forked `src/Worker.js` instance, but talking
//! newline-delimited JSON over stdio instead of Node's IPC channel.

use serde_json::Value;
use std::io::{BufRead, BufReader, Write};
use std::process::{Child, ChildStdin, ChildStdout, Command, Stdio};

pub enum WorkerEvent {
    Status { status: String, msg: String },
    Update { name: String, quantity: f64 },
    Report { file: String, msg: String },
    Free,
    Disconnect,
    /// A raw (non-control) line of output produced by the transform itself
    /// (e.g. `console.log` from `--print`); must be echoed verbatim.
    Passthrough(String),
}

pub struct Worker {
    child: Child,
    stdin: ChildStdin,
    reader: BufReader<ChildStdout>,
}

const CONTROL_PREFIX: char = '\u{0000}';

impl Worker {
    pub fn spawn(node_bin: &str, bridge_script: &str, transform_file: &str, babel: bool) -> std::io::Result<Worker> {
        let mut child = Command::new(node_bin)
            .arg(bridge_script)
            .arg(transform_file)
            .arg(if babel { "babel" } else { "no-babel" })
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::inherit())
            .spawn()?;
        let stdin = child.stdin.take().unwrap();
        let stdout = child.stdout.take().unwrap();
        Ok(Worker {
            child,
            stdin,
            reader: BufReader::new(stdout),
        })
    }

    pub fn send(&mut self, files: &[String], options: &Value) -> std::io::Result<()> {
        let msg = serde_json::json!({ "files": files, "options": options });
        writeln!(self.stdin, "{}", msg)?;
        self.stdin.flush()
    }

    /// Blocks reading the next event from the worker. Returns `None` on EOF.
    pub fn next_event(&mut self) -> std::io::Result<Option<WorkerEvent>> {
        let mut line = String::new();
        let n = self.reader.read_line(&mut line)?;
        if n == 0 {
            return Ok(None);
        }
        let line = line.trim_end_matches('\n').trim_end_matches('\r');
        if let Some(rest) = line.strip_prefix(CONTROL_PREFIX) {
            let v: Value = serde_json::from_str(rest).unwrap_or(Value::Null);
            let action = v.get("action").and_then(|a| a.as_str()).unwrap_or("");
            let event = match action {
                "status" => WorkerEvent::Status {
                    status: v.get("status").and_then(|s| s.as_str()).unwrap_or("").to_string(),
                    msg: v.get("msg").and_then(|s| s.as_str()).unwrap_or("").to_string(),
                },
                "update" => WorkerEvent::Update {
                    name: v.get("name").and_then(|s| s.as_str()).unwrap_or("").to_string(),
                    quantity: v.get("quantity").and_then(|q| q.as_f64()).unwrap_or(1.0),
                },
                "report" => WorkerEvent::Report {
                    file: v.get("file").and_then(|s| s.as_str()).unwrap_or("").to_string(),
                    msg: v.get("msg").and_then(|s| s.as_str()).unwrap_or("").to_string(),
                },
                "free" => WorkerEvent::Free,
                "disconnect" => WorkerEvent::Disconnect,
                _ => WorkerEvent::Passthrough(line.to_string()),
            };
            Ok(Some(event))
        } else {
            Ok(Some(WorkerEvent::Passthrough(line.to_string())))
        }
    }

    pub fn wait(&mut self) -> std::io::Result<std::process::ExitStatus> {
        self.child.wait()
    }
}
"}

{"command":"create","path":"/workspace/codebase/rust-cli/src/ignore.rs","file_text":"//! Port of `src/ignoreFiles.js`.
//!
//! Implements the same gitignore-pattern-to-glob approximation and the same
//! matching semantics (`dot: true`, leading-traversal-prefix stripping) as
//! the original, using a small glob engine (see `glob.rs`) instead of the
//! `picomatch` npm package.

use crate::glob::glob_match;

pub struct IgnoreSet {
    matchers: Vec<String>,
}

impl IgnoreSet {
    pub fn new() -> Self {
        IgnoreSet { matchers: Vec::new() }
    }

    fn add_pattern(&mut self, val: &str) {
        if val.is_empty() || val.starts_with('#') {
            return;
        }
        let pattern = val;
        if !pattern.contains('/') {
            self.matchers.push(format!("**/{}", pattern));
        } else if pattern.ends_with('/') {
            self.matchers.push(format!("**/{}**", pattern));
            self.matchers.push(format!("{}**", pattern));
        }
        self.matchers.push(pattern.to_string());
    }

    pub fn add(&mut self, input: &[String]) {
        for p in input {
            self.add_pattern(p);
        }
    }

    pub fn add_from_file(&mut self, path: &str) -> std::io::Result<()> {
        let meta = std::fs::metadata(path)?;
        if meta.is_file() {
            let content = std::fs::read_to_string(path)?;
            for line in content.split(['\n']) {
                let line = line.strip_suffix('\r').unwrap_or(line);
                self.add_pattern(line);
            }
        }
        Ok(())
    }

    pub fn should_ignore(&self, path: &str) -> bool {
        if self.matchers.is_empty() {
            return false;
        }
        if glob_match_any(path, &self.matchers) {
            return true;
        }
        let normalized = strip_leading_traversal(path);
        if normalized != path && glob_match_any(&normalized, &self.matchers) {
            return true;
        }
        false
    }
}

fn strip_leading_traversal(path: &str) -> String {
    let mut s = path;
    loop {
        if let Some(rest) = s.strip_prefix("../") {
            s = rest;
        } else if let Some(rest) = s.strip_prefix("./") {
            s = rest;
        } else if let Some(rest) = s.strip_prefix("..\\") {
            s = rest;
        } else if let Some(rest) = s.strip_prefix(".\\") {
            s = rest;
        } else {
            break;
        }
    }
    s.to_string()
}

fn glob_match_any(path: &str, patterns: &[String]) -> bool {
    patterns.iter().any(|p| glob_match(p, path, true))
}
"}

{"command":"create","path":"/workspace/codebase/rust-cli/src/glob.rs","file_text":"//! Minimal glob matcher supporting the subset of picomatch semantics used
//! by `src/ignoreFiles.js`: `*`, `**`, `?`, character classes `[...]`, and
//! `dot: true` matching (so `*`/`**` also match dotfiles/dot-directories,
//! which is the one non-default picomatch option jscodeshift relies on).
//!
//! The pattern is compiled into a regular expression using the same
//! translation approach picomatch itself uses, and matched against the
//! path with both `/` and `\\` treated as separators (paths are normalized
//! to `/` before matching, mirroring picomatch's default `windows`
//! handling on POSIX plus straightforward compatibility on Windows).

use regex::Regex;

pub fn glob_match(pattern: &str, path: &str, _dot: bool) -> bool {
    let re = match compile(pattern) {
        Some(re) => re,
        None => return false,
    };
    let normalized = path.replace('\\', "/");
    re.is_match(&normalized)
}

fn compile(pattern: &str) -> Option<Regex> {
    let pattern = pattern.replace('\\', "/");
    let mut re = String::from("^");
    let chars: Vec<char> = pattern.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        match c {
            '*' => {
                if i + 1 < chars.len() && chars[i + 1] == '*' {
                    // `**`
                    let is_slash_globstar = (i + 2 >= chars.len() || chars[i + 2] == '/')
                        && (i == 0 || chars[i - 1] == '/');
                    if is_slash_globstar {
                        if i + 2 < chars.len() && chars[i + 2] == '/' {
                            re.push_str("(?:.*/)?");
                            i += 3;
                            continue;
                        } else {
                            re.push_str(".*");
                            i += 2;
                            continue;
                        }
                    } else {
                        re.push_str(".*");
                        i += 2;
                        continue;
                    }
                } else {
                    re.push_str("[^/]*");
                    i += 1;
                    continue;
                }
            }
            '?' => {
                re.push_str("[^/]");
                i += 1;
                continue;
            }
            '[' => {
                let mut j = i + 1;
                let mut class = String::from("[");
                if j < chars.len() && (chars[j] == '!' || chars[j] == '^') {
                    class.push('^');
                    j += 1;
                }
                let start = j;
                while j < chars.len() && chars[j] != ']' {
                    j += 1;
                }
                if j >= chars.len() {
                    // Unterminated class: treat `[` literally.
                    re.push_str("\\[");
                    i += 1;
                    continue;
                }
                let body: String = chars[start..j].iter().collect();
                class.push_str(&regex_escape_class_body(&body));
                class.push(']');
                re.push_str(&class);
                i = j + 1;
                continue;
            }
            '.' | '+' | '(' | ')' | '|' | '^' | '$' | '{' | '}' => {
                re.push('\\');
                re.push(c);
                i += 1;
                continue;
            }
            _ => {
                re.push(c);
                i += 1;
                continue;
            }
        }
    }
    re.push('$');
    Regex::new(&re).ok()
}

fn regex_escape_class_body(body: &str) -> String {
    // Character class contents are mostly passed through, but escape a
    // literal backslash so it doesn't create an unintended escape.
    body.replace('\\', "\\\\")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn matches_basic_glob() {
        assert!(glob_match("*.js", "foo.js", true));
        assert!(!glob_match("*.js", "foo.ts", true));
        assert!(glob_match("**/node_modules/**", "a/b/node_modules/c/d.js", true));
        assert!(glob_match("**/node_modules/**", "node_modules/c/d.js", true));
        assert!(glob_match("**/.git/**", "a/.git/x", true));
        assert!(glob_match("foo/", "foo/bar", false) == false); // literal, unless suffixed with **
    }
}
"}

{"thought":"My glob compile function's ** handling is messy. Let me rewrite using a cleaner segment-based approach:

Split pattern by '/' preserving empty segments info, but easier: do char-scanning with explicit rules:
1. If we see "**" and it's a standalone segment (bounded by '/' or start/end), then:
   - if followed by '/' -> consume "**/" and emit "(?:.*/)?"
   - if preceded by '/' and at pattern end -> already consumed by previous of this same iteration... let's handle preceding by emitting "(?:/.*)?" when we encounter "/**" at the end.

Simplify: I'll preprocess the pattern string with regex replacements at the segment level before char-by-char translation isn't feasible since other special chars need escaping too. Let's do a full rewrite: tokenize into segments by outside-bracket '/', then process each token, then join with translated separators, handling "**" tokens specially relative to neighboring slashes.

Given time constraints, let's implement it as: split pattern into path segments by '/', producing vec of segments (strings, may be empty for leading/trailing slash i.e strings like "" ). Then build regex by iterating segments with index, joining appropriately:

- For each segment equal to "**":
  - if it's the only segment -> ".*"
  - if first segment -> "(?:.*/)?" then continue without emitting a "/" before next (since (?:.*/)? already includes trailing slash optionally)
  - if last segment -> "(?:/.*)?" prepended appropriately (no leading "/" before since we add "(?:/.*)?" replacing the "/**" entirely)
  - if middle segment -> "(?:.*/)?" but need slash before and after handled contextually - simplify to ".*/" ... 

This is getting complex; picomatch itself has intricate handling. Given time constraints and that this is only used for ignore patterns (not exhaustive test suite), let's implement a reasonably correct common-case version:

Algorithm:
1. Split pattern on '/' into segments (keep empty strings for leading/trailing slashes, but ignore-pattern usage typically doesn't have leading slash based on addIgnorePattern logic which prepends "**/" itself).
2. For output, process segment list:
   - result_parts: Vec<String> of regex fragments per segment (translated, without slashes)
   - Then join: but "**" segments need special joining logs done during join.

Simpler approach mirroring common minimatch-lite conversion:
regex = pattern
 replace occurrences of "**/" -> "(?:.*/)?" 
 replace occurrences of "/**" -> "(?:/.*)?"
 replace remaining "**" -> ".*"
 replace "*" -> "[^/]*"
 replace "?" -> "[^/]"
