enum Token {
    Literal(String),
    Star,
    GlobStar { leading_slash: bool, trailing_slash: bool },
    Question,
    Class(String),
    Slash,
}

fn tokenize(pattern: &str) -> Vec<Token> {
    let chars: Vec<char> = pattern.chars().collect();
    let mut tokens = Vec::new();
    let mut i = 0;
    while i < chars.len() {
        match chars[i] {
            '/' => {
                tokens.push(Token::Slash);
                i += 1;
            }
            '*' => {
                if i + 1 < chars.len() && chars[i + 1] == '*' {
                    let leading_slash = i == 0 || chars[i - 1] == '/';
                    let after = i + 2;
                    let trailing_slash = after >= chars.len() || chars[after] == '/';
                    tokens.push(Token::GlobStar { leading_slash, trailing_slash });
                    i += 2;
                } else {
                    tokens.push(Token::Star);
                    i += 1;
                }
            }
            '?' => {
                tokens.push(Token::Question);
                i += 1;
            }
            '[' => {
                let mut j = i + 1;
                let mut class = String::from("[");
                if j < chars.len() && (chars[j] == '!' || chars[j] == '^') {
                    class.push('^');
                    j += 1;
                }
                let start = j;
                while j < chars.len() && chars[j] != ']' {
                    j += 1;
                }
                if j >= chars.len() {
                    tokens.push(Token::Literal("\\[".to_string()));
                    i += 1;
                    continue;
                }
                let body: String = chars[start..j].iter().collect();
                class.push_str(&regex_escape_class_body(&body));
                class.push(']');
                tokens.push(Token::Class(class));
                i = j + 1;
            }
            c @ ('.' | '+' | '(' | ')' | '|' | '^' | '$' | '{' | '}' | '\\') => {
                tokens.push(Token::Literal(format!("\\{}", c)));
                i += 1;
            }
            c => {
                tokens.push(Token::Literal(c.to_string()));
                i += 1;
            }
        }
    }
    tokens
}

fn compile(pattern: &str) -> Option<Regex> {
    let pattern = pattern.replace('\\', "/");
    let tokens = tokenize(&pattern);
    let mut re = String::from("^");
    let mut i = 0;
    while i < tokens.len() {
        match &tokens[i] {
            Token::Slash => {
                re.push('/');
                i += 1;
            }
            Token::Star => {
                re.push_str("[^/]*");
                i += 1;
            }
            Token::Question => {
                re.push_str("[^/]");
                i += 1;
            }
            Token::Class(c) => {
                re.push_str(c);
                i += 1;
            }
            Token::Literal(s) => {
                re.push_str(s);
                i += 1;
            }
            Token::GlobStar { leading_slash, trailing_slash } => {
                if *leading_slash && *trailing_slash {
