use std::io::IsTerminal;

fn is_color_supported() -> bool {
    if std::env::var_os("NO_COLOR").is_some() {
        return false;
    }
    if std::env::args().any(|a| a == "--no-color") {
        return false;
    }
    if std::env::var_os("FORCE_COLOR").is_some() {
        return true;
    }
    if std::env::args().any(|a| a == "--color") {
        return true;
    }
    if cfg!(windows) {
        return true;
    }
    if std::io::stdout().is_terminal() && std::env::var("TERM").ok().as_deref() != Some("dumb") {
        return true;
    }
    std::env::var_os("CI").is_some()
}

pub struct Colors {
    enabled: bool,
}

impl Colors {
    pub fn detect() -> Colors {
        Colors { enabled: is_color_supported() }
    }

    fn wrap(&self, open: &str, close: &str, s: &str) -> String {
        if !self.enabled {
            return s.to_string();
        }
        format!("{}{}{}", open, s, close)
    }

    pub fn red(&self, s: &str) -> String {
        self.wrap("\x1b[31m", "\x1b[39m", s)
    }
    pub fn green(&self, s: &str) -> String {
        self.wrap("\x1b[32m", "\x1b[39m", s)
    }
    pub fn yellow(&self, s: &str) -> String {
        self.wrap("\x1b[33m", "\x1b[39m", s)
    }
    pub fn blue(&self, s: &str) -> String {
        self.wrap("\x1b[34m", "\x1b[39m", s)
    }
    pub fn white(&self, s: &str) -> String {
        self.wrap("\x1b[37m", "\x1b[39m", s)
    }
    pub fn bg_green(&self, s: &str) -> String {
        self.wrap("\x1b[42m", "\x1b[49m", s)
    }
    pub fn bg_yellow(&self, s: &str) -> String {
        self.wrap("\x1b[43m", "\x1b[49m", s)
    }
    pub fn bg_red(&self, s: &str) -> String {
        self.wrap("\x1b[41m", "\x1b[49m", s)
    }
    pub fn bg_blue(&self, s: &str) -> String {
        self.wrap("\x1b[44m", "\x1b[49m", s)
    }
}
"}

