use crate::colors::Colors;
use crate::ignore::IgnoreSet;
use crate::worker::{Worker, WorkerEvent};
use serde_json::Value;
use std::collections::BTreeMap;
use std::io::Write;
use std::path::Path;
use std::time::Instant;

const CHUNK_SIZE: usize = 50;

pub struct RunOptions {
    pub cpus: Option<u32>,
    pub extensions: Option<String>,
    pub ignore_pattern: Vec<String>,
    pub ignore_config: Vec<String>,
    pub gitignore: bool,
    pub babel: bool,
    pub dry: bool,
    pub print: bool,
    pub run_in_band: bool,
    pub silent: bool,
    pub verbose: i64,
    pub fail_on_error: bool,
    /// Full set of parsed options, forwarded verbatim to the transform (as
    /// `options` in the old Worker.js/`transform(file, api, options)`
    /// contract), matching the original's behavior of passing the whole
    /// parsed argv object through.
    pub raw_options: Value,
}

pub struct RunResult {
    pub stats: BTreeMap<String, f64>,
    pub time_elapsed: String,
    pub error: u64,
    pub ok: u64,
    pub nochange: u64,
    pub skip: u64,
}

fn available_cpus() -> u32 {
    std::cmp::max(num_cpus::get() as i64 - 1, 1) as u32
}

fn line_break(s: &str) -> String {
    if s.ends_with('\n') {
        s.to_string()
    } else {
        format!("{}\n", s)
    }
}

fn dir_files(dir: &Path, ignores: &IgnoreSet, out: &mut Vec<String>) -> std::io::Result<()> {
    let entries = match std::fs::read_dir(dir) {
        Ok(e) => e,
        Err(e) => return Err(e),
    };
    for entry in entries {
        let entry = entry?;
        let path = entry.path();
        let name = path.to_string_lossy().to_string();
        let meta = match std::fs::symlink_metadata(&path) {
            Ok(m) => m,
            Err(_) => {
                println!("Skipping path \"{}\" which does not exist.", name);
                continue;
            }
        };
        if ignores.should_ignore(&name) {
            continue;
        }
        let stat = if meta.file_type().is_symlink() {
            match std::fs::metadata(&path) {
                Ok(m) => m,
                Err(_) => {
                    println!("Skipping path \"{}\" which does not exist.", name);
                    continue;
                }
            }
        } else {
            meta
        };
        if stat.is_dir() {
            dir_files(&path, ignores, out)?;
        } else {
            out.push(name);
        }
    }
    Ok(())
}

fn get_all_files(paths: &[String], ignores: &IgnoreSet, filter: impl Fn(&str) -> bool) -> Vec<String> {
    let mut result = Vec::new();
    for file in paths {
        let meta = match std::fs::symlink_metadata(file) {
            Ok(m) => m,
            Err(_) => {
                eprintln!("Skipping path {} which does not exist. ", file);
                continue;
            }
        };
        if meta.is_dir() {
            let mut collected = Vec::new();
            if dir_files(Path::new(file), ignores, &mut collected).is_ok() {
                result.extend(collected.into_iter().filter(|f| filter(f)));
            }
        } else if !filter(file) || ignores.should_ignore(file) {
            // ignored
        } else {
            result.push(file.clone());
        }
    }
    result
}

fn show_file_stats(c: &Colors, error: u64, nochange: u64, skip: u64, ok: u64) {
    print!(
        "Results: \n{}{}{}{}",
        c.red(&format!("{} errors\n", error)),
        c.yellow(&format!("{} unmodified\n", nochange)),
        c.yellow(&format!("{} skipped\n", skip)),
        c.green(&format!("{} ok\n", ok)),
    );
}

fn show_stats(c: &Colors, stats: &BTreeMap<String, f64>) {
    if !stats.is_empty() {
        print!("{}", c.blue("Stats: \n"));
    }
    for (name, value) in stats {
        println!("{}: {}", name, value);
    }
}

pub fn run(
    node_bin: &str,
    bridge_script: &str,
    transform_file: &str,
    paths: &[String],
    options: RunOptions,
) -> std::io::Result<RunResult> {
    let colors = Colors::detect();
    let available = available_cpus();
    let cpus = options.cpus.map(|c| std::cmp::min(available, c)).unwrap_or(available);
    let extensions: Option<Vec<String>> = options
        .extensions
        .as_ref()
        .map(|s| s.split(',').map(|e| format!(".{}", e)).collect());

    let mut ignores = IgnoreSet::new();
    ignores.add(&options.ignore_pattern);
    for f in &options.ignore_config {
        let _ = ignores.add_from_file(f);
    }
    if options.gitignore {
        if let Ok(cwd) = std::env::current_dir() {
            let gi = cwd.join(".gitignore");
            let _ = ignores.add_from_file(&gi.to_string_lossy());
        }
    }

    let start_time = Instant::now();

    if !Path::new(transform_file).exists() && !transform_file.starts_with("http") {
        eprintln!(
            "{} Transform file {} does not exist ",
            colors.bg_red(&colors.white("ERROR")),
            transform_file
        );
        return Ok(RunResult {
            stats: BTreeMap::new(),
            time_elapsed: "0.000".to_string(),
            error: 0,
            ok: 0,
            nochange: 0,
            skip: 0,
        });
    }

    let files = get_all_files(paths, &ignores, |name| {
        extensions
            .as_ref()
            .map(|exts| {
                let ext = Path::new(name)
                    .extension()
                    .map(|e| format!(".{}", e.to_string_lossy()))
                    .unwrap_or_default();
                exts.iter().any(|e| e == &ext)
            })
            .unwrap_or(true)
    });

    let num_files = files.len();
    let mut error = 0u64;
    let mut ok = 0u64;
    let mut nochange = 0u64;
    let mut skip = 0u64;
    let mut stats_counter: BTreeMap<String, f64> = BTreeMap::new();

    if num_files == 0 {
        println!("No files selected, nothing to do. ");
        return Ok(RunResult {
            stats: stats_counter,
            time_elapsed: format!("{:.3}", start_time.elapsed().as_secs_f64()),
            error,
            ok,
            nochange,
            skip,
        });
    }

    let processes = if options.run_in_band { 1 } else { std::cmp::min(num_files as u32, cpus) as usize };
    let chunk_size = if processes > 1 { std::cmp::min((num_files + processes - 1) / processes, CHUNK_SIZE) } else { num_files };

    if !options.silent {
        println!("Processing {} files... ", num_files);
        if !options.run_in_band {
            println!("Spawning {} workers...", processes);
        }
        if options.dry {
            println!("{}", colors.green("Running in dry mode, no files will be written! "));
        }
    }

    let mut index = 0usize;
    let mut next = |silent: bool, run_in_band: bool| -> Vec<String> {
        if !silent && !run_in_band && index < num_files {
            let n = std::cmp::min(chunk_size, num_files - index);
            println!("Sending {} files to free worker...", n);
        }
        let start = index;
        let end = std::cmp::min(index + chunk_size, num_files);
        index = end;
        files[start..end].to_vec()
    };

    let mut workers: Vec<Worker> = Vec::new();
    for _ in 0..processes {
        let w = Worker::spawn(node_bin, bridge_script, transform_file, options.babel)?;
        workers.push(w);
    }

    for w in workers.iter_mut() {
        let batch = next(options.silent, options.run_in_band);
        w.send(&batch, &options.raw_options)?;
    }

    for w in workers.iter_mut() {
        loop {
            match w.next_event()? {
                None => break,
                Some(WorkerEvent::Status { status, msg }) => {
                    match status.as_str() {
                        "error" => error += 1,
                        "ok" => ok += 1,
                        "nochange" => nochange += 1,
                        "skip" => skip += 1,
                        _ => {}
                    }
                    let line = line_break(&msg);
                    let verbose = options.verbose;
                    match status.as_str() {
                        "ok" => {
                            if verbose >= 2 {
                                print!("{}{}", colors.bg_green(&colors.white(" OKK ")), line);
                            }
                        }
                        "nochange" => {
                            if verbose >= 1 {
                                print!("{}{}", colors.bg_yellow(&colors.white(" NOC ")), line);
                            }
                        }
                        "skip" => {
                            if verbose >= 1 {
                                print!("{}{}", colors.bg_yellow(&colors.white(" SKIP ")), line);
                            }
                        }
                        "error" => {
                            if verbose >= 0 {
                                print!("{}{}", colors.bg_red(&colors.white(" ERR ")), line);
                            }
                        }
                        _ => {}
                    }
                    std::io::stdout().flush().ok();
                }
                Some(WorkerEvent::Update { name, quantity }) => {
                    *stats_counter.entry(name).or_insert(0.0) += quantity;
                }
                Some(WorkerEvent::Free) => {
                    let batch = next(options.silent, options.run_in_band);
                    w.send(&batch, &options.raw_options)?;
                }
                Some(WorkerEvent::Report { file, msg }) => {
                    println!("{}", line_break(&format!("{}{} {}", colors.bg_blue(&colors.white(" REP ")), file, msg)));
                }
                Some(WorkerEvent::Disconnect) => {
                    break;
                }
                Some(WorkerEvent::Passthrough(line)) => {
                    println!("{}", line);
                }
            }
        }
        w.wait()?;
    }

    let time_elapsed = format!("{:.3}", start_time.elapsed().as_secs_f64());

    if !options.silent {
        println!("All done. ");
        show_file_stats(&colors, error, nochange, skip, ok);
        show_stats(&colors, &stats_counter);
        println!("Time elapsed: {}seconds ", time_elapsed);

        if options.fail_on_error && error > 0 {
            std::process::exit(1);
        }
    }

    Ok(RunResult {
        stats: stats_counter,
        time_elapsed,
        error,
        ok,
        nochange,
        skip,
    })
}
"}

