mod args;
mod colors;
mod glob;
mod ignore;
mod runner;
mod worker;

use args::{spec, ArgsError, OptionSpec};
use serde_json::Value;
use std::io::{Read, Write};
use std::path::{Path, PathBuf};

fn repo_root() -> PathBuf {
    // rust-cli/target/.../jscodeshift -> repo root is two levels above
    // rust-cli/ (i.e. the crate's parent directory), matching the layout
    // used by the original `bin/jscodeshift.js`, which lives in
    // `<repo>/bin/`.
    let exe_dir = std::env::current_exe().ok().and_then(|p| p.parent().map(|p| p.to_path_buf()));
    // Prefer CARGO_MANIFEST_DIR at build time isn't available at runtime,
    // so fall back to locating the repo by walking up from the current
    // working directory / executable looking for package.json.
    if let Some(dir) = exe_dir {
        if let Some(root) = find_repo_root(&dir) {
            return root;
        }
    }
    if let Some(root) = find_repo_root(&std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."))) {
        return root;
    }
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).parent().unwrap().to_path_buf()
}

fn find_repo_root(start: &Path) -> Option<PathBuf> {
    let mut dir = start.to_path_buf();
    loop {
        if dir.join("package.json").is_file() && dir.join("bridge").join("transform-host.js").is_file() {
            return Some(dir);
        }
        match dir.parent() {
            Some(p) => dir = p.to_path_buf(),
            None => return None,
        }
    }
}

fn read_json_field(path: &Path, key: &str) -> Option<String> {
    let content = std::fs::read_to_string(path).ok()?;
    let v: Value = serde_json::from_str(&content).ok()?;
    v.get(key)?.as_str().map(|s| s.to_string())
}

fn require_package_version(root: &Path, name: &str) -> String {
    let pkg_json = root.join("node_modules").join(name).join("package.json");
    read_json_field(&pkg_json, "version").unwrap_or_default()
}

fn version_text(root: &Path) -> String {
    let pkg_version = read_json_field(&root.join("package.json"), "version").unwrap_or_default();
    format!(
        "jscodeshift: {}\n - babel: {}\n - babylon: {}\n - flow: {}\n - recast: {}\n\n",
        pkg_version,
        require_package_version(root, "@babel/core"),
        require_package_version(root, "@babel/parser"),
        require_package_version(root, "flow-parser"),
        require_package_version(root, "recast"),
    )
}

fn extensions_default() -> &'static str {
    "cjs,es,es6,js,jsx,mjs,ts,tsx"
}

fn find_node_bin() -> String {
    std::env::var("JSCODESHIFT_NODE_BIN").unwrap_or_else(|_| "node".to_string())
}

fn main() {
    let root = repo_root();

    let mut options: Vec<OptionSpec> = spec();
    for o in options.iter_mut() {
        if o.key == "extensions" {
            o.default = Some(Value::String(extensions_default().to_string()));
        }
    }

    let argv: Vec<String> = std::env::args().skip(1).collect();

    let parsed = match args::parse(&options, &argv, || version_text(&root)) {
        Ok(p) => p,
        Err(ArgsError { exit_code, message }) => {
            if exit_code != 0 {
                eprint!("{}", message);
            } else {
                print!("{}", message);
            }
            std::process::exit(exit_code);
        }
    };

    if let Some(text) = parsed.callback_output {
        print!("{}", text);
        std::process::exit(0);
    }

    let get_bool = |m: &std::collections::HashMap<String, Value>, k: &str| -> bool {
        m.get(k).and_then(|v| v.as_bool()).unwrap_or(false)
    };
    let get_str = |m: &std::collections::HashMap<String, Value>, k: &str| -> Option<String> {
        m.get(k).and_then(|v| v.as_str()).map(|s| s.to_string())
    };
    let get_num = |m: &std::collections::HashMap<String, Value>, k: &str| -> Option<f64> {
        m.get(k).and_then(|v| v.as_f64())
    };
    let get_list = |m: &std::collections::HashMap<String, Value>, k: &str| -> Vec<String> {
        m.get(k)
            .and_then(|v| v.as_array())
            .map(|a| a.iter().filter_map(|x| x.as_str().map(|s| s.to_string())).collect())
            .unwrap_or_default()
    };

    let positional: Vec<String> = parsed
        .positional
        .iter()
        .map(|v| match v {
            Value::String(s) => s.clone(),
            other => other.to_string(),
        })
        .collect();

    let stdin_mode = get_bool(&parsed.options, "stdin");

    if positional.is_empty() && !stdin_mode {
        let help = args::get_help_text(&options);
        eprint!(
            "Error: You have to provide at least one file/directory to transform.\n\n---\n\n{}",
            help
        );
        std::process::exit(1);
    }

    let transform_opt = get_str(&parsed.options, "transform").unwrap_or_else(|| "./transform.js".to_string());
    let transform_file = if transform_opt.starts_with("http://") || transform_opt.starts_with("https://") {
        transform_opt
    } else {
        std::fs::canonicalize(&transform_opt)
            .map(|p| p.to_string_lossy().to_string())
            .unwrap_or_else(|_| {
                let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
                cwd.join(&transform_opt).to_string_lossy().to_string()
            })
    };

    let raw_options = Value::Object(parsed.options.clone().into_iter().collect());

    let run_options = runner::RunOptions {
        cpus: get_num(&parsed.options, "cpus").map(|n| n as u32),
        extensions: get_str(&parsed.options, "extensions"),
        ignore_pattern: get_list(&parsed.options, "ignorePattern"),
        ignore_config: get_list(&parsed.options, "ignoreConfig"),
        gitignore: get_bool(&parsed.options, "gitignore"),
        babel: get_bool(&parsed.options, "babel"),
        dry: get_bool(&parsed.options, "dry"),
        print: get_bool(&parsed.options, "print"),
        run_in_band: get_bool(&parsed.options, "runInBand"),
        silent: get_bool(&parsed.options, "silent"),
        verbose: get_num(&parsed.options, "verbose").unwrap_or(0.0) as i64,
        fail_on_error: get_bool(&parsed.options, "failOnError"),
        raw_options,
    };

    let node_bin = find_node_bin();
    let bridge_script = root.join("bridge").join("transform-host.js").to_string_lossy().to_string();

    let paths: Vec<String> = if stdin_mode {
        let mut buffer = String::new();
        std::io::stdin().read_to_string(&mut buffer).ok();
        buffer.split('\n').map(|s| s.to_string()).collect()
    } else {
        positional
    };

    let result = runner::run(&node_bin, &bridge_script, &transform_file, &paths, run_options);
    if let Err(e) = result {
        eprintln!("Runner error: {}", e);
        std::process::exit(1);
    }
    std::io::stdout().flush().ok();
}
