fn download_transform(url: &str) -> Result<String, String> {
    let resp = ureq::get(url).call().map_err(|e| e.to_string())?;
    let mut body = String::new();
    resp.into_reader()
        .read_to_string(&mut body)
        .map_err(|e| e.to_string())?;
    let ext = Path::new(url).extension().map(|e| format!(".{}", e.to_string_lossy())).unwrap_or_default();
    let mut tmp = tempfile::Builder::new()
        .prefix("jscodeshift")
        .suffix(&ext)
        .tempfile()
        .map_err(|e| e.to_string())?;
    use std::io::Write as _;
    tmp.write_all(body.as_bytes()).map_err(|e| e.to_string())?;
    let (_, path) = tmp.keep().map_err(|e| e.to_string())?;
    Ok(path.to_string_lossy().to_string())
}

